int maxSum(int arr[], int n, int k) {
    int max_sum = 0;
    int window_sum = 0;
    for (int i = 0; i < k; i++) {
        window_sum += arr[i]; // Sum of the first window
    }
    max_sum = window_sum;
    for (int i = k; i < n; i++) {
        window_sum += arr[i] - arr[i - k];
        max_sum = max(max_sum, window_sum);
    }
    return max_sum;
}

